32	int cfl_variant_print(FILE *fp, struct cfl_variant *val)
33	{
34	    int ret = -1;
35	    size_t size;
36	    size_t i;
37	
38	    if (fp == NULL || val == NULL) {
39	        return -1;
40	    }
41	
42	    switch (val->type) {
43	    case CFL_VARIANT_STRING:
44	        ret = fprintf(fp, "\"%s\"", val->data.as_string);
45	        break;
46	    case CFL_VARIANT_BOOL:
47	        if (val->data.as_bool) {
48	            ret = fputs("true",fp);
49	        }
50	        else {
51	            ret = fputs("false", fp);
52	        }
53	        break;
54	    case CFL_VARIANT_INT:
55	        ret = fprintf(fp, "%" PRId64, val->data.as_int64);
56	        break;
57	    case CFL_VARIANT_UINT:
58	        ret = fprintf(fp, "%" PRIu64, val->data.as_uint64);
59	        break;
60	    case CFL_VARIANT_DOUBLE:
61	        ret = fprintf(fp, "%lf", val->data.as_double);
62	        break;
63	    case CFL_VARIANT_NULL:
64	        ret = fprintf(fp, "null");
65	        break;
66	    case CFL_VARIANT_BYTES:
67	        size = cfl_sds_len(val->data.as_bytes);
68	        for (i=0; i<size; i++) {
69	            ret = fprintf(fp, "%02x", (unsigned char)val->data.as_bytes[i]);
70	        }
71	        break;
72	
73	    case CFL_VARIANT_REFERENCE:
74	        ret = fprintf(fp, HEXDUMPFORMAT, val->data.as_reference);
75	        break;
76	    case CFL_VARIANT_ARRAY:
77	        ret = cfl_array_print(fp, val->data.as_array);
78	        break;
79	
80	    case CFL_VARIANT_KVLIST:
81	        ret = cfl_kvlist_print(fp, val->data.as_kvlist);
82	        break;
83	
84	    default:
85	        ret = fputs("!Unknown Type", fp);
86	    }
87	    return ret;
88	}
