Here are the two requested functions from the CFL source (Apache License 2.0):

## `cfl_array_create`

```c
struct cfl_array *cfl_array_create(size_t slot_count)
{
    struct cfl_array *array;
    size_t alloc_count;

    array = malloc(sizeof(struct cfl_array));
    if (array == NULL) {
        cfl_errno();
        return NULL;
    }

    /* by default arrays are not resizable */
    array->resizable = CFL_FALSE;

    /* allocate fixed number of entries */
    alloc_count = slot_count;
    if (alloc_count == 0) {
        alloc_count = 1;
    }
    if (alloc_count > SIZE_MAX / sizeof(void *)) {
        free(array);
        return NULL;
    }

    array->entries = calloc(alloc_count, sizeof(void *));
    if (array->entries == NULL) {
        cfl_errno();
        free(array);
        return NULL;
    }

    array->entry_count = 0;
    array->slot_count = slot_count;
    array->owner = NULL;
    array->parent_array = NULL;
    array->parent_kvlist = NULL;

    return array;
}
```

## `cfl_array_append`

```c
int cfl_array_append(struct cfl_array *array,
                     struct cfl_variant *value)
{
    void *tmp;
    size_t new_slot_count;
    size_t new_size;
    size_t base_slot_count;

    if (array == NULL || value == NULL) {
        return -1;
    }

    if (array->entry_count >= array->slot_count) {
        if (array->resizable) {
            base_slot_count = array->slot_count;
            if (base_slot_count == 0) {
                base_slot_count = 1;
            }

            /* set new number of slots and total size */
            if (base_slot_count > SIZE_MAX / 2) {
                return -1;
            }

            new_slot_count = (base_slot_count * 2);
            if (new_slot_count > SIZE_MAX / sizeof(void *)) {
                return -1;
            }

            new_size = (new_slot_count * sizeof(void *));

            tmp = realloc(array->entries, new_size);
            if (!tmp) {
                cfl_report_runtime_error();
                return -1;
            }
            array->slot_count = new_slot_count;
            array->entries = tmp;
        }
        else {
            return -1;
        }
    }

    /* this is just a double check to make sure the slot is really available */
    if (array->entry_count >= array->slot_count) {
        return -1;
    }

    if (cfl_container_move_variant_to_array(array, value) != 0) {
        return -1;
    }

    array->entries[array->entry_count++] = value;
    return 0;
}
```

## How the zero `slot_count` case is handled

**In `cfl_array_create`:** The stored `slot_count` field keeps the original value passed in (which could be 0). Only the local `alloc_count` used for the actual allocation is bumped to 1 when zero, described as `"allocate fixed number of entries"`. So an array can be created with a stored `slot_count` of 0.

**In `cfl_array_append`:** When resizing, the code guards against a zero base by copying `slot_count` into `base_slot_count` and forcing it to 1 if it's zero, before doubling. This prevents the doubling operation from producing 0 (since `0 * 2 == 0`). It then applies overflow checks — first ensuring `base_slot_count` doesn't exceed `SIZE_MAX / 2`, then verifying the new count fits within `SIZE_MAX / sizeof(void *)` — before reallocating. The comment notes this doubling should be used when the caller `"knows this is safe to do"` because it controls the input data.

