    /* by default arrays are not resizable */
    array->resizable = CFL_FALSE;

    /*
     * always allocate at least one slot so the array is a valid, non-NULL
     * instance even when the caller requested zero slots. The reported
     * slot_count is kept as requested so appends are still rejected until
     * the array is made resizable.
