    alloc_count = slot_count;
    if (alloc_count == 0) {
        alloc_count = 1;
    }

    /* allocate fixed number of entries */
    array->entries = calloc(alloc_count, sizeof(void *));
    if (array->entries == NULL) {
        cfl_errno();
        free(array);
        return NULL;
    }

    array->entry_count = 0;
